{"code":"import solver

def trial(s):
    r = solver.trial(network_id="snem-sa-2000", operation="load_scale", scale=s,
                     observation="bus_voltage", observation_id=2008, max_iter=50)
    return r["data"]["metric"]

# Bisection to find s such that V(2008) = 0.9422 pu
lo, hi = 0.9, 1.1
target = 0.9422
for _ in range(30):
    mid = (lo + hi) / 2.0
    v = trial(mid)
    if v < target:
        lo = mid
    else:
        hi = mid

print(f"{(lo + hi) / 2.0:.6f}")"}

